        "code": "// 1. Guardar y recuperar datos básicos\nsessionStorage.setItem('tempData', 'valor temporal');\nconst temp = sessionStorage.getItem('tempData');\nconsole.log(temp); // \"valor temporal\"\n\n// 2. Guardar estado de formulario en sesión\nfunction saveFormProgress() {\n  const form = document.querySelector('form');\n  const formData = new FormData(form);\n  const data = Object.fromEntries(formData.entries());\n  sessionStorage.setItem('formProgress', JSON.stringify(data));\n}\n\nfunction restoreFormProgress() {\n  const saved = sessionStorage.getItem('formProgress');\n  if (saved) {\n    const data = JSON.parse(saved);\n    Object.entries(data).forEach(([key, value]) => {\n      const input = document.querySelector(`[name=\"${key}\"]`);\n      if (input) input.value = value;\n    });\n  }\n}\n\n// 3. Prevenir envío duplicado de formulario\ndocument.querySelector('form').addEventListener('submit', (e) => {\n  const formId = e.target.id || 'default-form';\n\n  if (sessionStorage.getItem(`submitted_${formId}`)) {\n    e.preventDefault();\n    alert('Este formulario ya fue enviado en esta sesión');\n    return;\n  }\n\n  sessionStorage.setItem(`submitted_${formId}`, 'true');\n  // Enviar formulario...\n});\n\n// 4. Guardar scroll position para \"volver atrás\"\ndocument.addEventListener('scroll', () => {\n  sessionStorage.setItem('scrollPosition', window.scrollY.toString());\n});\n\n// Al cargar la página\ndocument.addEventListener('DOMContentLoaded', () => {\n  const scrollPos = sessionStorage.getItem('scrollPosition');\n  if (scrollPos) {\n    window.scrollTo(0, parseInt(scrollPos));\n  }\n});\n\n// 5. Navegación con estado en SPA\nconst stateHistory = [];\n\nfunction navigateTo(route, data) {\n  // Guardar estado actual en sessionStorage\n  const state = {\n    route: route,\n    data: data,\n    timestamp: Date.now()\n  };\n  stateHistory.push(state);\n  sessionStorage.setItem('navigationHistory', JSON.stringify(stateHistory));\n\n  // Navegar\n  renderRoute(route, data);\n}\n\nfunction goBack() {\n  const history = JSON.parse(sessionStorage.getItem('navigationHistory') || '[]');\n  if (history.length > 1) {\n    history.pop(); // Quitar actual\n    const previous = history[history.length - 1];\n    sessionStorage.setItem('navigationHistory', JSON.stringify(history));\n    renderRoute(previous.route, previous.data);\n  }\n}\n\n// 6. Wizard de varios pasos\nclass WizardSession {\n  constructor(wizardId) {\n    this.wizardId = wizardId;\n    this.storageKey = `wizard_${wizardId}`;\n  }\n\n  saveStep(step, data) {\n    const wizardData = this.getData();\n    wizardData.steps[step] = data;\n    wizardData.currentStep = step;\n    wizardData.updatedAt = Date.now();\n    sessionStorage.setItem(this.storageKey, JSON.stringify(wizardData));\n  }\n\n  getData() {\n    const saved = sessionStorage.getItem(this.storageKey);\n    return saved ? JSON.parse(saved) : { steps: {}, currentStep: 0 };\n  }\n\n  getStep(step) {\n    const data = this.getData();\n    return data.steps[step] || null;\n  }\n\n  getCurrentStep() {\n    return this.getData().currentStep;\n  }\n\n  isComplete() {\n    const data = this.getData();\n    const totalSteps = Object.keys(data.steps).length;\n    return totalSteps > 0 && data.currentStep === totalSteps - 1;\n  }\n\n  clear() {\n    sessionStorage.removeItem(this.storageKey);\n  }\n}\n\n// Uso\nconst wizard = new WizardSession('signup');\nwizard.saveStep(1, { name: 'Juan', email: 'juan@email.com' });\nwizard.saveStep(2, { password: '******' });\nconsole.log(wizard.isComplete());\n\n// 7. Detectar si es la primera visita en esta sesión\nfunction isFirstVisitInSession() {\n  if (!sessionStorage.getItem('visited')) {\n    sessionStorage.setItem('visited', 'true');\n    return true;\n  }\n  return false;\n}\n\n// 8. Cache temporal de API (solo esta sesión)\nclass SessionCache {\n  static get(key) {\n    const cached = sessionStorage.getItem(`cache_${key}`);\n    if (!cached) return null;\n\n    const { data, timestamp } = JSON.parse(cached);\n    const TTL = 5 * 60 * 1000; // 5 minutos\n\n    if (Date.now() - timestamp > TTL) {\n      sessionStorage.removeItem(`cache_${key}`);\n      return null;\n    }\n\n    return data;\n  }\n\n  static set(key, data) {\n    sessionStorage.setItem(`cache_${key}`, JSON.stringify({\n      data,\n      timestamp: Date.now()\n    }));\n  }\n\n  static clear() {\n    const keys = Object.keys(sessionStorage);\n    keys.filter(k => k.startsWith('cache_'))\n        .forEach(k => sessionStorage.removeItem(k));\n  }\n}\n\n// 9. Guardar notificaciones temporales\nfunction showNotification(message, type = 'info') {\n  const notifications = JSON.parse(sessionStorage.getItem('notifications') || '[]');\n  notifications.push({\n    message,\n    type,\n    timestamp: Date.now(),\n    id: Date.now()\n  });\n\n  // Mantener solo últimas 20\n  if (notifications.length > 20) {\n    notifications.splice(0, notifications.length - 20);\n  }\n\n  sessionStorage.setItem('notifications', JSON.stringify(notifications));\n  renderNotifications();\n}\n\n// 10. Seguimiento de actividad en sesión\nfunction trackUserActivity() {\n  const activity = JSON.parse(sessionStorage.getItem('activity') || '[]');\n  activity.push({\n    action: 'page_view',\n    page: window.location.pathname,\n    timestamp: Date.now()\n  });\n\n  // Mantener solo últimas 50 acciones\n  if (activity.length > 50) {\n    activity.splice(0, activity.length - 50);\n  }\n\n  sessionStorage.setItem('activity', JSON.stringify(activity));\n}",
